  const goals={origins:{order:['collateral-roots','medieval-tree','charter-bridge','surrounding-samples','farrier'],note:'Test the Norman-era model through collateral ancestry, branch dating and documented geography. A named immigrant or ancient sample would help, but is not a prerequisite for improving the historical picture.'},alexander:{order:['close-bundle','alexander-son','william-bundle','kilwaughter','ft6135','farrier','james-william','sapp-rerun','remaining'],note:'Prioritise direct comparison of existing close-match files and an independent Alexander son-line. This order focuses on the evidence most directly connected with Alexander’s family.'},surname:{order:['kilwaughter','james-william','farrier','close-bundle','william-bundle','alexander-son','ft6135','sapp-rerun','remaining'],note:'Prioritise unplaced East Antrim lines and cross-surname matches. A new branch-resolving test can discriminate between competing groupings better than another STR-only diagram.'},family:{order:['ft6135','sapp-rerun','close-bundle','william-bundle','alexander-son','kilwaughter','james-william','farrier','remaining'],note:'Resolve the actual per-site calls before arguing about Robert’s genotype. Pedigree mapping, SNP assignment and the observed call at FT6135 remain separate fields.'}};
  function renderActions(){const goal=goals[$('research-goal').value];$('goal-note').textContent=goal.note;$('action-list').innerHTML=goal.order.map((id,i)=>{const a=actions[id];return `<article class="action-card"><span class="action-number">${i+1}</span><div>${status(a.type,a.type.startsWith('New')?'amber':'teal')}<h3>${esc(a.title)}</h3><p class="action-summary">${esc(a.summary)}</p><div class="action-outcomes"><div><span>What this adds to the family story</span><p>${esc(a.result)}</p></div></div><details><summary>Method, dependencies and source priority</summary><p>${esc(a.detail)}</p><p>${esc(a.limit)}</p><p>${a.original?'Original page priority: '+a.original+'. This ordering follows the selected research goal.':'A focused extension of the supplied research plan.'} ${source(a.source||'S0')}</p></details></div></article>`}).join('')}
