  function renderSources(){$('source-list').innerHTML=D.sources.map(s=>`<article class="source-row" id="source-${s.id}"><span class="source-number">${s.id}</span><div><h3>${s.url?extLink(s.url,s.title):esc(s.title)}</h3><p>${esc(s.detail)}</p></div><div class="source-date">${status(s.type,s.type==='New calculation'?'teal':s.type==='Supplied source'?'neutral':'blue')}<span>${esc(s.date)}</span></div></article>`).join('');$('analysis-audit-table').innerHTML=`<table><thead><tr><th>Issue</th><th>Revised handling</th></tr></thead><tbody>${auditRows.map(r=>`<tr><th>${esc(r[0])}</th><td>${esc(r[1])}</td></tr>`).join('')}</tbody></table>`;}
  async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);toast('Copied to clipboard.');return;}}catch(e){}const area=document.createElement('textarea');area.value=text;area.setAttribute('readonly','');area.style.position='fixed';area.style.top='-9999px';document.body.append(area);area.select();let ok=false;try{ok=document.execCommand('copy')}catch(e){}area.remove();if(ok)toast('Copied to clipboard.');else{const dialog=document.createElement('dialog');dialog.innerHTML='<form method="dialog"><h3>Copy this text</h3><textarea readonly style="width:min(75vw,650px);height:180px;margin:16px 0"></textarea><br><button class="button" type="submit">Close</button></form>';dialog.querySelector('textarea').value=text;document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();dialog.querySelector('textarea').select();}}
